llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Retosiban, a peptidomimetic with multiple amide bonds, had absolute oral bioavailability of 17–25% in healthy female subjects, straddling the 20% threshold; this is the only evidence approaching the threshold and does not affirmatively support high F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Melagatran, a polar peptidomimetic with a basic amidine, had human oral bioavailability of only 0.9–7%, indicating extensive first-pass elimination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Remikiren, a large peptidomimetic renin inhibitor, had absolute oral bioavailability of 0.2–0.3% in healthy volunteers across multiple doses.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "DX-9065a, containing strong basic amidino groups, had human oral bioavailability of only 2–3%, attributed to the basic groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "MK-458, a moderately lipophilic morphinan-like molecule, had absolute oral bioavailability of ~5% in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Nintedanib, a heteroaromatic kinase inhibitor with ester/amide groups, had absolute oral bioavailability of ~5% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Rebamipide, a polar heteroaromatic molecule, had human oral bioavailability under 10%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "A highly transferable basic amine-containing molecule had estimated absolute oral bioavailability of only 3% in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable human absolute-bioavailability records for structurally related peptidomimetic/heteroaromatic molecules show F <10% (mostly 0.2–7%); the only near-threshold value (retosiban 17–25%) is borderline and outweighed. The query's large, H-bond-rich, basic-amine-containing structure is consistent with poor permeability and extensive first-pass elimination. Therefore F <20% is strongly supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query molecule.",
    "Retosiban's 17–25% range straddles the threshold, leaving some uncertainty.",
    "No formulation, food-effect, or transporter-mediated efflux data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

